import 'package:flutter/material.dart';import '../core/utils/formatters.dart';import '../data/repositories/expense_repository.dart';
class RecurringScreen extends StatefulWidget{const RecurringScreen({super.key});@override State<RecurringScreen> createState()=>_RecurringScreenState();}
class _RecurringScreenState extends State<RecurringScreen>{final repo=ExpenseRepository();late Future<List<Map<String,Object?>>> future;@override void initState(){super.initState();future=repo.recurring();}void reload()=>setState(()=>future=repo.recurring());
 @override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('Recurring payments')),body:FutureBuilder<List<Map<String,Object?>>>(future:future,builder:(c,s){if(!s.hasData)return const Center(child:CircularProgressIndicator());if(s.data!.isEmpty)return const Center(child:Text('No recurring items added yet.'));return ListView(padding:const EdgeInsets.all(16),children:s.data!.map((e){final active=(e['is_active'] as int)==1;return Card(child:SwitchListTile(value:active,onChanged:(v)async{await repo.toggleRecurring(e['id'] as int,v);reload();},title:Text(e['title'] as String,style:const TextStyle(fontWeight:FontWeight.w700)),subtitle:Text((e['frequency'] as String)+' • '+(e['category_name'] as String? ?? 'Category')+' • next '+Fmt.date(DateTime.fromMillisecondsSinceEpoch(e['next_date_ms'] as int))),secondary:Text(Fmt.money((e['amount_minor'] as int)/100)));}).toList());}),floatingActionButton:FloatingActionButton.extended(onPressed:add,icon:const Icon(Icons.add),label:const Text('Add recurring')));
 Future<void> add()async{final title=TextEditingController(),amount=TextEditingController();final cats=await repo.categories(type:'expense'),accounts=await repo.accounts();if(cats.isEmpty||accounts.isEmpty)return;int category=cats.first['id'] as int,account=accounts.first['id'] as int;String frequency='monthly';final ok=await showDialog<bool>(context:context,builder:(c)=>StatefulBuilder(builder:(c,setD)=>AlertDialog(title:const Text('New recurring item'),content:SingleChildScrollView(child:Column(mainAxisSize:MainAxisSize.min,children:[TextField(controller:title,decoration:const InputDecoration(labelText:'Name')),TextField(controller:amount,keyboardType:TextInputType.number,decoration:const InputDecoration(labelText:'Amount',prefixText:'₹ ')),DropdownButtonFormField<int>(value:category,items:cats.map((e)=>DropdownMenuItem(value:e['id'] as int,child:Text(e['name'] as String))).toList(),onChanged:(v)=>setD(()=>category=v!)),DropdownButtonFormField<int>(value:account,items:accounts.map((e)=>DropdownMenuItem(value:e['id'] as int,child:Text(e['name'] as String))).toList(),onChanged:(v)=>setD(()=>account=v!)),DropdownButtonFormField<String>(value:frequency,items:const[DropdownMenuItem(value:'weekly',child:Text('Weekly')),DropdownMenuItem(value:'monthly',child:Text('Monthly')),DropdownMenuItem(value:'yearly',child:Text('Yearly'))],onChanged:(v)=>setD(()=>frequency=v!))])),actions:[TextButton(onPressed:()=>Navigator.pop(c,false),child:const Text('Cancel')),TextButton(onPressed:()=>Navigator.pop(c,true),child:const Text('Save'))])));final n=double.tryParse(amount.text);if(ok==true&&title.text.trim().isNotEmpty&&n!=null&&n>0){await repo.addRecurring(title.text.trim(),(n*100).round(),'expense',category,account,frequency,DateTime.now());reload();}title.dispose();amount.dispose();}
}
